## 问题5 [optimization]
你在PCB中定义了死锁检测相关的数据结构：

<code>
pub struct ProcessControlBlock {
    // ...其他字段...

    // LAB5: 死锁检测
    pub deadlock_detect: bool,
    pub available: Vec<usize>,        // 每类资源可用数
    pub allocation: Vec<Vec<usize>>,  // 每个线程的已分配资源
    pub request: Vec<Vec<usize>>,     // 每个线程的请求资源
}

impl ProcessControlBlock {
    pub fn new(...) -> Self {
        // 初始化...
        Self {
            // ...
            deadlock_detect: false,
            available: vec![0; MAX_RESOURCE_TYPES],
            allocation: vec![vec![0; MAX_RESOURCE_TYPES]; MAX_THREADS],
            request: vec![vec![0; MAX_RESOURCE_TYPES]; MAX_THREADS],
        }
    }
